package com.alpharip.staffmod.AuditFindingsBoard; public final class AuditFindingEvidenceReference {private final String label,reference,addedBy;private final long addedAt;public AuditFindingEvidenceReference(String l,String r,String by,long at){if(l==null||l.trim().isEmpty()||r==null||r.trim().isEmpty())throw new IllegalArgumentException("Evidence label and reference are required");label=l.trim();reference=r.trim();addedBy=by==null?"":by.trim();addedAt=Math.max(0L,at);}public String getLabel(){return label;}public String getReference(){return reference;}public String getAddedBy(){return addedBy;}public long getAddedAt(){return addedAt;} }
